def rank_from_table(trace, crit):
    """The cointegration rank from Johansen's trace statistics and critical values,
    both listed from r = 0 down, by the sequential rule."""
    if len(trace) != len(crit):
        raise ValueError("trace and crit must have the same length")
    for r, (stat, cv) in enumerate(zip(trace, crit)):
        if stat < cv:
            return r            # first failure to reject
    return len(trace)           # every row rejected: all series stationary
